import { Mic } from 'lucide-react';

// Phase 1: rendered but inert, so the input bar layout is final and voice
// input can be wired straight into this component in Phase 3 without
// reshuffling the rest of the footer.
export default function VoiceButton({ disabled = true, listening = false, onClick }) {
  return (
    <button
      type="button"
      className={`rl-input-bar__mic ${listening ? 'rl-input-bar__mic--listening' : ''}`}
      onClick={onClick}
      disabled={disabled}
      aria-label={disabled ? 'Voice input — coming soon' : 'Start voice input'}
      title={disabled ? 'Voice input coming soon' : 'Speak your answer'}
    >
      <Mic size={17} strokeWidth={2.2} />
    </button>
  );
}
